$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'स्वचालित सेटअप केवल इस साइट URL के लिए वेबहुक बनाता है, या उसमें छूटे हुए इवेंट जोड़ता है और अन्य सभी इवेंट बनाए रखता है। यह सिग्नेचर सत्यापित करने के लिए उपयोग होने वाली वेबहुक ID सहेजता है। यह कभी वेबहुक नहीं हटाता, कभी अन्य URL को नहीं छूता और कभी ऐप अनुमतियाँ नहीं बदलता।';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'स्वचालित सेटअप के लिए Webhook Endpoints: Write आवश्यक है। यह वेबहुक बनाता है और उसका नया साइनिंग सीक्रेट सुरक्षित रूप से सहेजता है, या मौजूदा एंडपॉइंट को सक्षम करके छूटे हुए इवेंट जोड़ता है। यह मौजूदा इवेंट बनाए रखता है और एंडपॉइंट नहीं बदलता या API कुंजी अनुमतियाँ नहीं बदलता।';
