$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'रिलीज़ नंबर और AVideo डेटाबेस संस्करण स्वतंत्र हैं। कोड अपडेट की स्थिति कमिट इतिहास से निर्धारित होती है।';
$t['The request to the social network failed. Please try again later.'] = 'सोशल नेटवर्क को भेजा गया अनुरोध विफल रहा। कृपया बाद में पुनः प्रयास करें।';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'रीस्ट्रीमर सर्वर गंतव्य तक नहीं पहुँच पा रहा है। नेटवर्क कनेक्टिविटी जाँचें।';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'समस्या जारी रहने तक वही अलर्ट अधिकतम हर %s में दोहराया जाता है।';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'समस्या जारी रहने तक वही अलर्ट अधिकतम हर कुछ घंटों में दोहराया जाता है।';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'चयनित कैमरा या माइक्रोफ़ोन उपलब्ध नहीं है। कृपया कोई अन्य डिवाइस चुनें।';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'चयनित स्थिति एक वास्तविक पेज पर हाइलाइट की गई है। मोबाइल प्रीव्यू केवल ADs की स्थितियाँ बदलता है; पेज का बाकी हिस्सा आपके ब्राउज़र डिवाइस का उपयोग करता है।';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'चुनी गई पोज़िशन आपकी साइट के एक असली पेज पर हाइलाइट की जाती है और नीचे आपके द्वारा चुनी गई पोज़िशन के अनुसार बदलती है। मोबाइल प्रीव्यू केवल विज्ञापनों की पोज़िशन बदलता है; पेज का बाकी हिस्सा आपके ब्राउज़र डिवाइस के अनुसार दिखता है।';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'डेटाबेस समस्या के कारण साइट अभी ऑफ़लाइन है। हम समस्या को जल्द से जल्द हल करने पर काम कर रहे हैं।';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'सर्वर की डिस्क भर जाने के कारण साइट अस्थायी रूप से अनुपलब्ध है। हम इस समस्या पर काम कर रहे हैं और जल्द ही वापस आएँगे।';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'सर्वर की डिस्क लगभग भर जाने के कारण साइट का रखरखाव चल रहा है। हम समस्या का समाधान कर रहे हैं और जल्द ही वापस आएँगे।';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'साइट ने पहुँच अस्वीकार कर दी। एनकोडर खाते की पहुँच नवीनीकृत करें और उसकी अपलोड अनुमतियाँ जाँचें।';
$t['The site will display only a login form to un authenticated users'] = 'The site will display only a login form to un authenticated users';
