$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'स्ट्रीम में टाइमस्टैम्प असंततताएँ हैं। इससे गंतव्य प्लेटफ़ॉर्म पर बफ़रिंग या प्लेबैक समस्याएँ हो सकती हैं।';
$t['The subtitle has not been copied to the player yet.'] = 'सबटाइटल अभी तक प्लेयर में कॉपी नहीं किया गया है।';
